/* Local A4 PDF writer, limited to the report API used by this application. */
(()=>{const k=72/25.4, enc=new TextEncoder();const special={'—':151,'–':150,'…':133,'’':146,'“':147,'”':148,'€':128,'•':149};const hex=s=>Array.from(String(s),c=>{let n=special[c]??c.codePointAt(0);return (n<=255?n:63).toString(16).padStart(2,'0')}).join('');const num=n=>Number(n).toFixed(3);class PDF{constructor(){this.pages=[[]];this.size=9;this.bold=false;this.tc=[0,0,0];this.fc=[0,0,0];this.internal={pageSize:{getWidth:()=>210,getHeight:()=>297}}}setFont(_,s){this.bold=s==='bold';return this}setFontSize(s){this.size=s;return this}setTextColor(...c){this.tc=c;return this}setFillColor(...c){this.fc=c;return this}color(c){return (c.length===1?[c[0],c[0],c[0]]:c).map(x=>num(x/255)).join(' ')}push(s){this.pages.at(-1).push(s)}width(s){return Array.from(s).reduce((a,c)=>a+(/[ilI.,:;!|']/u.test(c)?.28:/[MW@]/u.test(c)?.95:/[A-Z]/u.test(c)?.72:.57),0)*this.size/k}splitTextToSize(s,w){let out=[];for(const para of String(s).split('\n')){let line='';for(const word of para.split(/\s+/)){if(line&&this.width(line+' '+word)>w){out.push(line);line=''}if(this.width(word)>w){for(const c of word){if(this.width(line+c)>w){out.push(line);line=''}line+=c}}else line+=(line?' ':'')+word}out.push(line)}return out}rect(x,y,w,h){this.push(`${this.color(this.fc)} rg ${num(x*k)} ${num((297-y-h)*k)} ${num(w*k)} ${num(h*k)} re f`);return this}text(s,x,y,o={}){(Array.isArray(s)?s:[s]).forEach((t,i)=>{t=String(t);let xx=x-(o.align==='right'?this.width(t):o.align==='center'?this.width(t)/2:0);this.push(`BT /F${this.bold?2:1} ${num(this.size)} Tf ${this.color(this.tc)} rg 1 0 0 1 ${num(xx*k)} ${num((297-y)*k-i*this.size*1.15)} Tm <${hex(t)}> Tj ET`)});return this}addPage(){this.pages.push([]);return this}output(){let objs=['','<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];let kids=[];for(const p of this.pages){let id=objs.length,stream=p.join('\n');kids.push(id+' 0 R');objs.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${num(210*k)} ${num(297*k)}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${id+1} 0 R >>`,`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)}objs[2]=`<< /Type /Pages /Count ${kids.length} /Kids [${kids.join(' ')}] >>`;let pdf='%PDF-1.4\n',offset=[0];for(let i=1;i<objs.length;i++){offset.push(pdf.length);pdf+=`${i} 0 obj\n${objs[i]}\nendobj\n`}let x=pdf.length;pdf+=`xref\n0 ${objs.length}\n0000000000 65535 f \n`+offset.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objs.length} /Root 1 0 R >>\nstartxref\n${x}\n%%EOF\n`;return new Blob([enc.encode(pdf)],{type:'application/pdf'})}save(name){const url=URL.createObjectURL(this.output()),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}}window.jspdf={jsPDF:PDF};})();
